using Azure.Messaging.EventHubs;
using Azure.Messaging.EventHubs.Producer;
using Azure.Messaging.EventHubs.Consumer;

string connectionString = "Endpoint=sb://myhub.servicebus.windows.net/;SharedAccessKeyName=...";
string eventHubName = "telemetry";

// Send events
await using EventHubProducerClient producer = new EventHubProducerClient(connectionString, eventHubName);
using EventDataBatch batch = await producer.CreateBatchAsync();

for (int i = 0; i < 5; i++)
{
    EventData eventData = new EventData(BinaryData.FromString($"Reading {i}"));
    eventData.Properties["sensorId"] = i;
    batch.TryAdd(eventData);
}

await producer.SendAsync(batch);
Console.WriteLine("Batch sent.");

// Receive events (partition consumer)
string consumerGroup = EventHubConsumerClient.DefaultConsumerGroupName;
await using EventHubConsumerClient consumer = new EventHubConsumerClient(consumerGroup, connectionString, eventHubName);

await foreach (PartitionEvent pe in consumer.ReadEventsAsync())
{
    Console.WriteLine($"Received: {pe.Data.EventBody}");
    break; // Read one event for demo
}
